import React from 'react'

function Productcard({ productName, price }) {
  return (
     <div
      style={{
        border: "2px solid black",
        padding: "15px",
        width: "250px",
        borderRadius: "10px",
        backgroundColor: "#f4f4f4",
        margin: "10px",
      }}
    >
      <h2>{props.productName}</h2>
      <p>Price: ₹{props.price}</p>
    </div>
  );
  
  
}

export default Productcard
